}

solution:
async function placeOrder(db, input) {
  return db.transaction(async tx => {
    const product = await tx.products.lockForUpdate(input.productId);
    if (!product || product.stock < input.quantity) throw new Error('OUT_OF_STOCK');
    await tx.products.decrementStock(input.productId, input.quantity);
    return tx.orders.create(input);
  });
}
